            if (!policy) {
                return {};
            }
            const newTaxCode = values.taxCode.trim();
            if (newTaxCode === currentTaxCode) {
                return {};
            }

            return validateTaxCode(policy, values);
        },
        [currentTaxCode, policy],
    );

    return (
